from pybricks.hubs import PrimeHub
from pybricks.parameters import Direction, Port
from pybricks.pupdevices import Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
prime_hub = PrimeHub()
rightmotor = Motor(Port.F, Direction.CLOCKWISE)
leftmotor = Motor(Port.B, Direction.COUNTERCLOCKWISE)
drive_base = DriveBase(leftmotor, rightmotor, 63, 100)


# The main program starts here.
drive_base.use_gyro(True)
drive_base.straight(-50)
drive_base.straight(600)
prime_hub.display.number(10)
wait(1000)
prime_hub.display.number(9)
wait(1000)
prime_hub.display.number(8)
wait(1000)
prime_hub.display.number(7)
wait(1000)
prime_hub.display.number(6)
wait(1000)
prime_hub.display.number(5)
wait(1000)
prime_hub.display.number(4)
wait(1000)
prime_hub.display.number(3)
wait(1000)
prime_hub.display.number(2)
wait(1000)
prime_hub.display.number(1)
wait(1000)
drive_base.turn(90)
